import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
smiB = '[Rh]([H])([Si](C)(OC)OC)(N1CCCC1)(P(C1CCCCC1)(C2CCCCC2)C3CCCCC3)OS(=O)(=O)C(F)(F)F'
m = Chem.MolFromSmiles(smiB); m = Chem.AddHs(m)
ps = AllChem.ETKDGv3(); ps.randomSeed = 0xf00d
AllChem.EmbedMolecule(m, ps); AllChem.MMFFOptimizeMolecule(m, maxIters=5000)
xyz = np.array(m.GetConformer().GetPositions())
def ang(a,b,c):
    v1 = xyz[a]-xyz[b]; v2 = xyz[c]-xyz[b]
    return np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2)))
names = {1:'Hhyd',2:'SiR',8:'N',13:'P',32:'Osul'}
for i in names:
    for j in names:
        if i<j: print(names[i],'Rh',names[j], round(ang(i,0,j),1))
    print(names[i],'Rh dist', round(np.linalg.norm(xyz[i]-xyz[0]),2))
