import numpy as np
from scipy.spatial import cKDTree
def rd(p):
    L=open(p).read().split('\n'); n=int(L[0]); els=[]; xyz=[]
    for line in L[2:2+n]:
        t=line.split(); els.append(t[0]); xyz.append([float(v) for v in t[1:4]])
    return els,np.array(xyz)
e0,x0=rd('assembled.xyz'); e1,x1=rd('opt3.xyz')
core=[(0,1,'Rh-N'),(0,15,'Rh-SiR'),(0,30,'Rh-Osul'),(0,38,'Rh-P'),(0,91,'Rh-Hhyd'),(0,92,'Rh-Si*'),(0,118,'Rh-Hbr'),(92,118,'Si*-Hbr'),(92,93,'Si*-Oq'),(13,93,'HN-Oq')]
for i,j,nm in core:
    print(nm, round(float(np.linalg.norm(x0[i]-x0[j])),2),'->',round(float(np.linalg.norm(x1[i]-x1[j])),2))
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'S':1.05,'P':1.07,'Si':1.11,'Rh':1.42}
t=cKDTree(x1); pairs=sorted(t.query_pairs(2.1))
bad=[]
