    d=np.linalg.norm(x1[i]-x1[j]); c=cov[e1[i]]+cov[e1[j]]
    if d < c-0.15: bad.append((d-c,d,i,j))
bad.sort()
print('bad contacts:', len(bad))
for b in bad[:8]: print('%+.2f d=%.2f %d %s %d %s'%(b[0],b[1],b[2],e1[b[2]],b[3],e1[b[3]]))
# donor geometry
Rh=x1[0]
for i,nm in [(1,'N'),(15,'SiR'),(30,'Osul'),(38,'P'),(91,'Hhyd'),(92,'Si*')]:
    v=x1[i]-Rh; v/=np.linalg.norm(v); print(nm,np.round(v,2))
print('max atom move from relaxed:', round(float(np.abs(x1-x0).max()),2))
